{"version":3,"file":"config.js","sources":["common/config.uts"],"sourcesContent":["// common/config.ts\r\nexport type AuthApiPaths = {\r\n  tenantId: string\r\n  clientId: string\r\n  grantType: string\r\n  appID: string\r\n}\r\n\r\n// ApiPaths 只引用已定义的 interface\r\nexport type ApiPaths = {\r\n  auth: AuthApiPaths\r\n}\r\n\r\n// 其他配置类型\r\nexport type ConfigInfo = {\r\n  name: string\r\n  versionCode: number\r\n  versionName: string\r\n  appId?: string\r\n  logo?: string\r\n  desc?: string\r\n  isCN?: boolean\r\n}\r\n\r\nexport type StorageKeys = {\r\n  token: string\r\n  refreshToken: string\r\n}\r\n\r\nexport type ProjectConfig = {\r\n  baseUrl: string\r\n  timeout: number\r\n  env: string\r\n  api: ApiPaths\r\n  storage: StorageKeys\r\n  configInfo: ConfigInfo\r\n  loginPagePath?: string\r\n  loginRequiredPaths?: string[]\r\n}\r\n\r\n// 环境配置\r\nconst ENV = 'prod' //  dev | prod\r\n\r\nconst API_CONFIG: UTSJSONObject = {\r\n  dev: {\r\n    baseUrl: 'http://192.168.1.222:8081',\r\n    timeout: 30000\r\n  },\r\n  prod: {\r\n    baseUrl: 'https://cmpapp.zdiot.cn/prod-api',\r\n    timeout: 30000\r\n  }\r\n}\r\n\r\nconst currentConfig = API_CONFIG[ENV] as UTSJSONObject\r\n\r\n// 导出配置对象\r\nexport const config: ProjectConfig = {\r\n  baseUrl: currentConfig['baseUrl'] as string,\r\n  timeout: currentConfig['timeout'] as number,\r\n  env: ENV,\r\n  \r\n  \r\n  api: {\r\n    auth: {\r\n      tenantId: '000000', // 租户ID\r\n      clientId: '12353d4772a25656d6d2a67d53353cc3',\r\n      grantType: 'xcx',\r\n      appID: 'wxef277996acc166c3'\r\n    },\r\n  },\r\n  \r\n  storage: {\r\n    token: 'access_token',\r\n    refreshToken: 'refresh_token',\r\n  },\r\n  \r\n  configInfo: {\r\n    name: '中导云卡',\r\n    versionCode: 1,\r\n    versionName: '1.0.0',\r\n    appId: 'your-app-id',\r\n    isCN: true,\r\n  },\r\n  loginPagePath: '',\r\n  loginRequiredPaths: []\r\n}\r\n\r\n//获取租户ID\r\nexport function getTenantId(): string {\r\n  return config.api.auth.tenantId\r\n}\r\n\r\n// 获取当前登录用户的 token\r\nexport function getToken(): string {\r\n  const token = uni.getStorageSync(config.storage.token)\r\n  if (token == null) {\r\n    return ''\r\n  }\r\n  return token as string\r\n}\r\n\r\n// 设置当前登录用户的 token\r\nexport function setToken(token: string, refreshToken: string = '') {\r\n  uni.setStorageSync(config.storage.token, token)\r\n  if (refreshToken.length > 0) {\r\n    uni.setStorageSync(config.storage.refreshToken, refreshToken)\r\n  }\r\n}\r\n\r\n// 清除当前登录用户的 token\r\nexport function clearToken() {\r\n  uni.removeStorageSync(config.storage.token)\r\n  uni.removeStorageSync(config.storage.refreshToken)\r\n}\r\n\r\n// 本地存储操作\r\nexport function setStorageSync(key: string, value: any) {\r\n  uni.setStorageSync(key, value)\r\n}\r\n\r\n// 从存储中获取值\r\nexport function getStorageSync(key: string): string {\r\n  return uni.getStorageSync(key) as string\r\n}\r\n\r\n// 从存储中移除值\r\nexport function removeStorageSync(key: string) {\r\n  uni.removeStorageSync(key)\r\n}\r\n\r\n//判断当前平台是否为微信小程序\r\nexport function isWechat(): boolean {\r\n  // #ifdef MP-WEIXIN\r\n  return true\r\n  // #endif\r\n  \r\n  return false\r\n}\r\n\r\n//判断当前平台是否为H5\r\nexport function isH5(): boolean {\r\n  // #ifdef H5\r\n  return true\r\n  // #endif\r\n  return false\r\n}\r\n\r\n//判断当前是国内版\r\nexport function isCN(): boolean {\r\n  // #ifdef VERSION_CN\r\n  return true\r\n  // #endif\r\n  return config.configInfo.isCN\r\n}\r\n\r\n//判断当前是否为国际版\r\nexport function isINT(): boolean {\r\n  // #ifdef VERSION_INT\r\n  return true\r\n  // #endif\r\n  return false\r\n}"],"names":["UTS","UTSJSONObject","uni"],"mappings":";;MACY,qBAAYA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;MAQZ,iBAAQA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;MAKR,mBAAUA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;MAUV,oBAAWA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;MAKX,sBAAaA,cAAA,IAAA,QAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;AAYzB,MAAM,MAAM;AAEZ,MAAM,aAA4B,IAAAC,cAAAA,cAAA;AAAA,EAChC,KAAK,IAAAA,cAAAA,cAAA;AAAA,IACH,SAAS;AAAA,IACT,SAAS;A